import { locale, t } from './i18n';
import { useEffect, useState } from 'react';
import { ArrowLeft, ArrowRight, ArrowUpRight, Check, CheckCheck, Clock3, FileText, Pencil, Play, Plus, Printer, Receipt, Trash2, Wallet, Sparkles, Paperclip, CircleHelp, Landmark, ChartColumn } from 'lucide-react';
import type { AppState, Command, CommandResult, CreditNote, Invoice, Project, ProjectInsight, TimeEntry, VatPeriod } from '../shared/types';
import { Badge, Button, Empty, PageHeader, PanelHeader } from './components';
import { country, date, duration, hours, money, statusLabels, today } from './format';

export type ModalName = 'client' | 'project' | 'time' | 'timer' | 'timerStop' | 'draft' | 'payment' | 'credit' | 'expense' | 'settings' | 'workspace' | 'deleteTime' | 'deleteExpense' | 'deleteDraft' | 'reversePayment' | 'issue' | 'vatFiling';
export type OpenModal = (type: ModalName, id?: string, projectId?: string) => void;
/** inline: rethrow the error so the open form can show it next to the retained input. */
export type RunOptions = { inline?: boolean };
export type Run = (command: Command, options?: RunOptions) => Promise<CommandResult | null>;
export type PageProps = { state: AppState; open: OpenModal; run: Run; busy: boolean; search: string; navigate: (page: string) => void; selectedInvoice: string | null; selectInvoice: (id: string | null) => void; selectedProject: string | null; selectProject: (id: string | null) => void; };
const projectName = (state: AppState, id: string) => state.projects.find(project => project.id === id)?.name || t("Project");
const clientName = (state: AppState, id: string) => state.clients.find(client => client.id === id)?.name || t("Client");
const projectClient = (state: AppState, id: string) => clientName(state, state.projects.find(project => project.id === id)?.clientId || '');
/** Only hourly work waits to be invoiced; time on a fixed project measures effort and is covered by the contract line. */
const readyToInvoice = (state: AppState, entry: TimeEntry) => entry.approved && entry.billable && !entry.invoiceId && state.projects.find(project => project.id === entry.projectId)?.kind === 'hourly';
const match = (search: string, ...fields: string[]) => fields.join(' ').toLowerCase().includes(search.toLowerCase());
const statusTone = (status: Project['status']) => status === 'complete' ? 'green' : status === 'cancelled' ? 'red' : status === 'quote' || status === 'paused' ? 'amber' : 'neutral';
const monthLabel = (month: string) => new Date(`${month}-01T12:00:00`).toLocaleDateString(locale(), { month: 'short' });
/** The latest finished VAT period that still has no recorded status. */
const openVatPeriod = (state: AppState): VatPeriod | undefined => state.vatPeriods.find(period => period.end < today() && !period.filing?.status.match(/filed|not-applicable/));
const sumMinutes = (entries: TimeEntry[]) => entries.reduce((total, entry) => total + entry.minutes, 0);
const newestFirst = <T extends { date: string; createdAt: string }>(a: T, b: T) => b.date.localeCompare(a.date) || b.createdAt.localeCompare(a.createdAt);
const monogram = (name: string) => name.split(/\s+/).filter(word => word && !/^(the|a|an)$/i.test(word)).slice(0, 2).map(word => word[0].toUpperCase()).join('') || name.slice(0, 1).toUpperCase();
/** Contribution stays unknown until costs are confirmed; zero confirmed hours gives no per-hour figure. Never shown as zero. */
export function unknownReason(insight: ProjectInsight | undefined): string | null {
  if (!insight || insight.contributionMinor === null) return t("Unknown — confirm direct costs");
  if (insight.contributionPerHourMinor === null) return t("Unknown — no confirmed hours yet");
  return null;
}

function Status({ invoice }: { invoice: Invoice }) {
  if (invoice.status === 'draft') return <Badge>{t("Draft")}</Badge>;
  if (invoice.outstandingMinor < 0) return <Badge tone="blue">{t("Refund due")}</Badge>;
  if (invoice.outstandingMinor === 0) return <Badge tone="green">{t("Settled")}</Badge>;
  if (invoice.dueDate < today()) return <Badge tone="amber">{t("Overdue")}</Badge>;
  if (invoice.paidMinor > 0) return <Badge tone="blue">{t("Part paid")}</Badge>;
  return <Badge tone="blue">{t("Awaiting payment")}</Badge>;
}
function PerHour({ insight, currency }: { insight: ProjectInsight | undefined; currency: string }) {
  const unknown = unknownReason(insight);
  return unknown ? <span className="unknown-value"><CircleHelp size={15}/>{unknown}</span> : <>{money(insight!.contributionPerHourMinor, currency)}<small>/h</small></>;
}
function Elapsed({ since }: { since: string }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 15_000); return () => window.clearInterval(timer); }, []);
  return <>{duration(Math.max(0, Math.floor((now - new Date(since).getTime()) / 60000)))}</>;
}
function Allocation({ entry, state, onOpen }: { entry: TimeEntry; state: AppState; onOpen: (id: string) => void }) {
  if (!entry.invoiceId) return !entry.billable ? <Badge>{t("Non-billable")}</Badge> : state.projects.find(project => project.id === entry.projectId)?.kind === 'fixed' ? <Badge tone="green">{t("In fixed price")}</Badge> : <Badge tone="green">{t("Billable")}</Badge>;
  const invoice = state.invoices.find(item => item.id === entry.invoiceId);
  return <button className="badge-button" onClick={() => onOpen(entry.invoiceId!)} title={t("Open the invoice that holds this time")}><Badge tone="blue">{invoice?.status === 'issued' ? t("Invoiced · {0}", invoice.number) : t("Reserved on draft")}</Badge></button>;
}

/**
 * RISE loop (0/25/50/75/100%): confirmed time rows → billable rows become invoice lines → invoice issued →
 * all hours, including the unpaid row, feed the return per hour. Decorative only; with reduced motion the final frame is static.
 */
function WorkflowMotion() {
  return <div className="workflow-motion" aria-hidden="true"><svg viewBox="0 0 220 82"><g className="wm-loop">
    <rect className="wm-track" x="166" y="52" width="48" height="10" rx="3"/><rect className="wm-bar" x="166" y="52" width="48" height="10" rx="3"/><text className="wm-label" x="166" y="44">{t("€ / hour")}</text>
    <rect className="wm-sheet" x="96" y="6" width="56" height="70" rx="4"/><rect className="wm-total" x="104" y="58" width="24" height="5" rx="2"/>
    <rect className="wm-row wm-row-1" x="4" y="14" width="64" height="12" rx="3"/><rect className="wm-row wm-row-2" x="4" y="32" width="64" height="12" rx="3"/><rect className="wm-unpaid" x="4" y="50" width="64" height="12" rx="3"/>
    <g className="wm-check"><circle cx="146" cy="12" r="7"/><path d="M142.6 12.2l2.4 2.4 4.6-4.8"/></g>
  </g></svg><div className="workflow-steps"><span>{t("Your time")}</span><span>{t("Invoice")}</span><span>{t("Real return")}</span></div></div>;
}

export function Overview(props: PageProps) {
  const { state, open, navigate, selectProject } = props;
  const currency = state.workspace.currency;
  const currentDate = new Date().toLocaleDateString(locale(), { weekday: 'long', day: 'numeric', month: 'long' });
  const ranked = [...state.insights].sort((a, b) => (b.contributionPerHourMinor ?? -Infinity) - (a.contributionPerHourMinor ?? -Infinity));
  const max = Math.max(1, ...ranked.map(item => Math.abs(item.contributionPerHourMinor || 0)));
  const review = state.timeEntries.filter(entry => !entry.approved && !entry.invoiceId);
  const ready = state.timeEntries.filter(entry => readyToInvoice(state, entry));
  const openProject = (id: string) => { navigate('Projects'); selectProject(id); };
  return <><PageHeader eyebrow={currentDate} title={t("Make your work count.")} text={t("A clear view of your time, your money, and the work worth doing.")}><Button icon={Plus} onClick={() => open('time')} disabled={!state.projects.length}>{t("Log time")}</Button></PageHeader>
    <section className="metrics" aria-label={t("Workspace totals")}>
      <div className="metric"><span className="metric-label">{t("Recorded revenue")}{' '}<ArrowUpRight size={16}/></span><strong>{money(state.totals.revenueMinor, currency)}</strong><small>{t("Net issued invoices, less credits")}</small></div>
      <button className="metric clickable" onClick={() => navigate('Time')}><span className="metric-label">{t("Ready to invoice")}{' '}<FileText size={16}/></span><strong>{money(state.totals.unbilledMinor, currency)}</strong><small>{t("Approved hourly work, before tax")}</small></button>
      <button className="metric clickable" onClick={() => navigate('Invoices')}><span className="metric-label">{t("Outstanding")}{' '}<Wallet size={16}/></span><strong>{money(state.totals.outstandingMinor, currency)}</strong><small>{t("Issued invoices after receipts & credits")}</small></button>
      <button className="metric clickable" onClick={() => navigate('Time')}><span className="metric-label">{t("Actual time worked")}{' '}<Clock3 size={16}/></span><strong>{hours(state.totals.workedMinutes)}</strong><small>{hours(state.totals.nonBillableMinutes)}{' '}{t("of non-billable work included")}</small></button>
    </section>
    <div className="overview-grid"><section className="panel yield-panel"><PanelHeader title={t("What is your work really worth?")} text={t("Direct contribution per actual hour worked · lifetime project totals")} action={t("View projects")} onAction={() => navigate('Projects')}/>
      {!state.projects.length ? <Empty title={t("Your first project starts here.")} text={t("Connect a client, a price and the time you actually spend.")} action={t("Create project")} onAction={() => open('project')}/> : <><div className="yield-chart">{ranked.slice(0, 8).map((insight, index) => {
        const project = state.projects.find(item => item.id === insight.projectId)!;
        const unknown = unknownReason(insight);
        return <button className="yield-row" key={insight.projectId} onClick={() => openProject(project.id)} aria-label={t("Open {0} for {1}", project.name, clientName(state, project.clientId))}><div className="yield-row-top"><div><span className="rank">0{index + 1}</span><span className="yield-name"><strong>{clientName(state, project.clientId)}</strong><small>{project.name}</small></span>{insight.provisional && <Badge>{t("In progress · provisional")}</Badge>}</div><span className={`yield-value ${unknown ? 'unknown' : ''}`}><PerHour insight={insight} currency={currency}/></span></div><div className={`bar-track ${unknown ? 'unknown' : ''}`}><div className={`bar-fill ${index === 0 ? 'first' : ''} ${(insight.contributionPerHourMinor ?? 0) < 0 ? 'negative' : ''}`} style={{ width: insight.contributionPerHourMinor === null ? '0%' : `${Math.max(2, Math.abs(insight.contributionPerHourMinor) / max * 100)}%` }}/></div><div className="yield-row-bottom"><span>{hours(insight.workedMinutes)}{' '}{t("worked ·")}{' '}{money(insight.revenueMinor, currency)}{' '}{t("net revenue")}</span><span>{insight.contributionMinor === null ? t("{0} costs so far · not confirmed", money(insight.directCostsMinor, currency)) : t("{0} direct costs", money(insight.directCostsMinor, currency))}</span></div></button>;
      })}</div><p className="panel-note">{t("Includes preparation, meetings and aftercare. Before general overhead and business taxes. Active projects are provisional. Select a project to see the records behind it.")}</p></>}
    </section><aside className="overview-rail"><section className="insight-card"><div className="insight-icon"><Sparkles size={23} strokeWidth={1.5}/></div><div className="eyebrow">{t("The whole picture")}</div><h2>{t("Every hour has")}<br/>{t("a place here.")}</h2><p>{t("Preparation. The extra meeting. That “quick” follow-up. Track it all to understand your real return.")}</p><WorkflowMotion/><button onClick={() => open('time')} className="light-link" disabled={!state.projects.length}>{t("Make time visible")}{' '}<ArrowRight size={17}/></button></section>
      <section className="panel next-actions"><PanelHeader title={t("A little forward motion")}/>{(() => { const vat = openVatPeriod(state); return <button onClick={() => navigate('Reports')}><span className="action-icon"><Landmark size={19}/></span><span><strong>{vat ? t("VAT return {0}: {1} {2}", vat.period, money(Math.abs(vat.balanceMinor), currency), vat.balanceMinor < 0 ? t("to reclaim") : t("to pay")) : t("VAT returns are up to date")}</strong><small>{vat ? t("Copy the boxes, then mark it filed") : t("See the current period in Reports")}</small></span><ArrowUpRight size={16}/></button>; })()}<button onClick={() => navigate('Time')}><span className="action-icon"><CheckCheck size={19}/></span><span><strong>{review.length ? (review.length === 1 ? t('1 time entry to review') : t('{0} time entries to review', review.length)) : t("Your time is up to date")}</strong><small>{t("Confirm duration and billability")}</small></span><ArrowUpRight size={16}/></button><button onClick={() => open('draft')} disabled={!state.projects.length}><span className="action-icon"><FileText size={19}/></span><span><strong>{ready.length ? t("Turn {0} of approved time into an invoice", hours(sumMinutes(ready))) : t("Create an invoice draft")}</strong><small>{t("Review everything before issuing")}</small></span><ArrowUpRight size={16}/></button><button onClick={() => open('workspace')}><span className="action-icon"><Wallet size={19}/></span><span><strong>{t("Your work. Your data.")}</strong><small>{t("Download a complete local backup")}</small></span><ArrowUpRight size={16}/></button></section>
    </aside></div>
    <section className="panel recent-panel"><PanelHeader title={t("The latest in your ledger")} text={t("Your most recent invoices")} action={t("All invoices")} onAction={() => navigate('Invoices')}/>{state.invoices.length ? <InvoiceTable {...props} invoices={[...state.invoices].reverse().slice(0, 4)}/> : <Empty title={t("Nothing invoiced yet.")} text={t("Your approved time is the starting point for your first invoice.")} icon={FileText}/>}</section>
  </>;
}

function InvoiceTable({ state, navigate, selectInvoice, invoices, showDue = false }: PageProps & { invoices: Invoice[]; showDue?: boolean }) {
  const view = (id: string) => { navigate('Invoices'); selectInvoice(id); };
  return <div className="table-scroll"><table className="stack-table"><thead><tr><th>{t("Document")}</th><th>{t("Client & project")}</th>{showDue && <th>{t("Due date")}</th>}<th>{t("Status")}</th><th className="numeric">{t("Total")}</th><th className="numeric">{t("Outstanding")}</th></tr></thead><tbody>{invoices.map(invoice => <tr key={invoice.id} className="clickable-row" onClick={() => view(invoice.id)}><td className="primary-cell"><button className="row-link" onClick={event => { event.stopPropagation(); view(invoice.id); }}>{invoice.number || t("Draft invoice")}</button><small className="cell-subtitle">{date(invoice.issueDate)}</small></td><td data-label={t("Client")}>{invoice.client.name}<small className="cell-subtitle">{projectName(state, invoice.projectId)}</small></td>{showDue && <td className="nowrap" data-label={t("Due")}>{date(invoice.dueDate)}</td>}<td data-label={t("Status")}><Status invoice={invoice}/></td><td className="numeric" data-label={t("Total")}>{money(invoice.totalMinor, invoice.currency)}</td><td className="numeric" data-label={t("Outstanding")}>{invoice.status === 'draft' ? '—' : money(invoice.outstandingMinor, invoice.currency)}</td></tr>)}</tbody></table></div>;
}

function TimeTable({ state, open, run, busy, entries, onInvoice, showProject = true }: { state: AppState; open: OpenModal; run: Run; busy: boolean; entries: TimeEntry[]; onInvoice: (id: string) => void; showProject?: boolean }) {
  const approve = (entry: TimeEntry) => run({ type: 'time.update', data: { id: entry.id, revision: entry.revision, projectId: entry.projectId, date: entry.date, minutes: entry.minutes, description: entry.description, category: entry.category, billable: entry.billable, approved: true } });
  return <div className="table-scroll"><table className="stack-table"><thead><tr><th>{t("Date")}</th><th>{t("Work")}{showProject && t(" & project")}</th><th>{t("Category")}</th><th className="numeric">{t("Time")}</th><th>{t("Billing")}</th><th>{t("Review")}</th><th aria-label={t("Actions")}/></tr></thead><tbody>{entries.map(entry => <tr key={entry.id}><td className="nowrap" data-label={t("Date")}>{date(entry.date)}</td><td className="primary-cell"><strong className="table-strong">{entry.description}</strong>{showProject && <small className="cell-subtitle">{projectName(state, entry.projectId)} · {projectClient(state, entry.projectId)}</small>}</td><td data-label={t("Category")}><span className="category-label">{entry.category}</span></td><td className="numeric nowrap" data-label={t("Time")}>{duration(entry.minutes)}</td><td data-label={t("Billing")}><Allocation entry={entry} state={state} onOpen={onInvoice}/></td><td data-label={t("Review")}>{entry.approved ? <span className="approved"><Check size={14}/>{' '}{t("Confirmed")}</span> : entry.date > today() ? <span className="muted">{t("Future proposal")}</span> : <Button variant="quiet" disabled={busy || !!entry.invoiceId} onClick={() => approve(entry)}>{t("Approve")}</Button>}</td><td className="actions-cell"><div className="row-actions"><button className="icon-button" disabled={!!entry.invoiceId || busy} onClick={() => open('time', entry.id)} aria-label={t("Edit {0}", entry.description)} title={entry.invoiceId ? t("Held by an invoice. Delete its draft first to edit.") : t("Edit")}><Pencil size={16}/></button><button className="icon-button" disabled={!!entry.invoiceId || busy} onClick={() => open('deleteTime', entry.id)} aria-label={t("Delete {0}", entry.description)} title={entry.invoiceId ? t("Held by an invoice") : t("Delete")}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table></div>;
}

export function TimePage({ state, open, run, busy, search, navigate, selectInvoice }: PageProps) {
  const [filter, setFilter] = useState('all');
  const entries = [...state.timeEntries].sort(newestFirst).filter(entry => match(search, entry.description, projectName(state, entry.projectId), projectClient(state, entry.projectId), entry.category)).filter(entry => filter === 'all' || (filter === 'review' && !entry.approved) || (filter === 'ready' && readyToInvoice(state, entry)) || (filter === 'nonbillable' && !entry.billable));
  const counts = { review: state.timeEntries.filter(entry => !entry.approved).length, ready: state.timeEntries.filter(entry => readyToInvoice(state, entry)).length };
  return <><PageHeader eyebrow={t("Keep an honest ledger")} title={t("Your time, accounted for.")} text={t("Track the delivery and all the work around it.")}><Button variant="secondary" icon={Play} disabled={!!state.timer || !state.projects.length} onClick={() => open('timer')}>{t("Start timer")}</Button><Button icon={Plus} disabled={!state.projects.length} onClick={() => open('time')}>{t("Log time")}</Button></PageHeader>
    {state.timer && <div className="timer-running" role="status"><span className="live-dot"/><div><strong>{t("Timer running ·")}{' '}<Elapsed since={state.timer.startedAt}/> · {projectName(state, state.timer.projectId)}</strong><small>{state.timer.description || state.timer.category}{' '}{t("· Started")}{' '}{new Date(state.timer.startedAt).toLocaleString([], { weekday: 'short', hour: '2-digit', minute: '2-digit' })}{' '}{t("· Not yet counted as work")}</small></div><Button variant="secondary" onClick={() => open('timerStop')}>{t("Stop & review")}</Button></div>}
    <section className="panel"><div className="table-toolbar"><div className="tabs" role="tablist" aria-label={t("Filter time")}>{[['all', t("All time")], ['review', t("Needs review{0}", counts.review ? ` · ${counts.review}` : '')], ['ready', t("Ready to invoice{0}", counts.ready ? ` · ${counts.ready}` : '')], ['nonbillable', t("Non-billable")]].map(([value, label]) => <button key={value} role="tab" aria-selected={filter === value} className={filter === value ? 'active' : ''} onClick={() => setFilter(value)}>{label}</button>)}</div><span className="muted count">{entries.length}{' '}{t("entries")}</span></div>{!state.projects.length ? <Empty title={t("Give your time a home.")} text={t("Create a client and project before logging your first hour.")} action={t("Create project")} onAction={() => open('project')} icon={Clock3}/> : !entries.length ? <Empty title={filter === 'all' && !search ? t("A fresh page in your time ledger.") : t("Nothing matches this view.")} text={filter === 'all' && !search ? t("Log your work manually, or start a timer and confirm the time when you stop.") : t("Try another filter or search term.")} action={filter === 'all' && !search ? t("Log time") : undefined} onAction={() => open('time')} icon={Clock3}/> : <TimeTable state={state} open={open} run={run} busy={busy} entries={entries} onInvoice={id => { navigate('Invoices'); selectInvoice(id); }}/>}</section><p className="footnote">{t("Confirmed time counts toward actual project effort, including non-billable work. Time held by a draft or issued invoice is protected; delete the draft first to make corrections. Unapproved entries are proposals and do not count yet.")}</p>
  </>;
}

export function ProjectsPage(props: PageProps) {
  const { state, open, search, selectedProject, selectProject } = props;
  const selected = state.projects.find(project => project.id === selectedProject);
  if (selected) return <ProjectDetail {...props} project={selected}/>;
  const projects = state.projects.filter(project => match(search, project.name, clientName(state, project.clientId)));
  return <><PageHeader eyebrow={t("Good work. Clear returns.")} title={t("A little more perspective.")} text={t("Keep the contract, costs and actual effort together.")}><Button variant="secondary" icon={Plus} onClick={() => open('client')}>{t("New client")}</Button><Button icon={Plus} onClick={() => open('project')}>{t("New project")}</Button></PageHeader><section className="project-grid">{projects.map(project => {
    const insight = state.insights.find(item => item.projectId === project.id);
    return <article className="project-card" key={project.id}><div className="project-card-top"><div className="project-monogram" aria-hidden="true">{monogram(project.name)}</div><Badge tone={statusTone(project.status)}>{statusLabels[project.status]}</Badge><button className="icon-button" onClick={() => open('project', project.id)} aria-label={t("Edit {0}", project.name)}><Pencil size={17}/></button></div><h2><button className="title-link" onClick={() => selectProject(project.id)}>{project.name}</button></h2><p className="project-client">{clientName(state, project.clientId)}</p><div className="project-yield"><span>{t("Contribution per actual hour")}</span><strong className={unknownReason(insight) ? 'unknown' : ''}><PerHour insight={insight} currency={state.workspace.currency}/></strong>{!project.costsComplete ? <small>{t("Mark direct costs as complete in the project to calculate return.")}</small> : insight?.provisional ? <small>{t("Provisional · project still in progress")}</small> : <small>{t("Before overhead and business taxes")}</small>}</div><dl className="project-facts"><div><dt>{t("Net revenue")}</dt><dd>{money(insight?.revenueMinor ?? 0, state.workspace.currency)}</dd></div><div><dt>{t("Actual effort")}</dt><dd>{hours(insight?.workedMinutes ?? 0)}</dd></div><div><dt>{t("Direct costs")}</dt><dd>{money(insight?.directCostsMinor ?? 0, state.workspace.currency)} {!project.costsComplete && <span className="muted">{t("so far")}</span>}</dd></div><div><dt>{project.kind === 'fixed' ? t("Fixed contract") : t("Hourly rate")}</dt><dd>{money(project.kind === 'fixed' ? project.fixedPriceMinor : project.rateMinor, state.workspace.currency)}{project.kind === 'hourly' && '/h'}</dd></div></dl><button className="project-action" onClick={() => selectProject(project.id)}>{t("Open project records")}{' '}<ArrowUpRight size={16}/></button></article>;
  })}</section>{!projects.length && <section className="panel"><Empty title={search ? t("No project matches this search.") : t("Make room for your next good project.")} text={search ? t("Try another name or client.") : t("Choose a client, set an hourly rate or fixed price, and start tracking the full picture.")} action={search ? undefined : t("Create project")} onAction={() => open('project')}/></section>}<section className="panel client-panel"><PanelHeader title={t("The people you work with")} text={t("Client details used on invoice documents")} action={t("Add client")} onAction={() => open('client')}/>{state.clients.length ? <div className="table-scroll"><table className="stack-table"><thead><tr><th>{t("Client")}</th><th>{t("Contact")}</th><th>{t("Country")}</th><th aria-label={t("Actions")}/></tr></thead><tbody>{state.clients.filter(client => match(search, client.name, client.email)).map(client => <tr key={client.id}><td className="primary-cell"><strong>{client.name}</strong><small className="cell-subtitle">{client.address.replace(/\s*\n\s*/g, ', ') || t("Address not set")}</small></td><td data-label={t("Contact")}>{client.contactName || client.email || '—'}{client.contactName && client.email && <small className="cell-subtitle">{client.email}</small>}</td><td data-label={t("Country")}>{country(client.country) || '—'}</td><td className="numeric actions-cell"><button className="icon-button" onClick={() => open('client', client.id)} aria-label={t("Edit {0}", client.name)}><Pencil size={16}/></button></td></tr>)}</tbody></table></div> : <Empty title={t("Your first client belongs here.")} text={t("An address and tax details can be added now or before you issue an invoice.")} action={t("Add client")} onAction={() => open('client')}/>}</section></>;
}

function ProjectDetail(props: PageProps & { project: Project }) {
  const { state, open, run, busy, project, navigate, selectInvoice, selectProject } = props;
  const currency = state.workspace.currency;
  const insight = state.insights.find(item => item.projectId === project.id);
  const entries = state.timeEntries.filter(entry => entry.projectId === project.id).sort(newestFirst);
  const confirmed = entries.filter(entry => entry.approved);
  const pending = entries.filter(entry => !entry.approved);
  const expenses = state.expenses.filter(expense => expense.projectId === project.id).sort(newestFirst);
  const invoices = state.invoices.filter(invoice => invoice.projectId === project.id).reverse();
  const worked = sumMinutes(confirmed), billable = sumMinutes(confirmed.filter(entry => entry.billable)), unpaid = worked - billable;
  const byCategory = [...new Set(confirmed.map(entry => entry.category))].map(category => ({ category, minutes: sumMinutes(confirmed.filter(entry => entry.category === category)) })).sort((a, b) => b.minutes - a.minutes);
  const unknown = unknownReason(insight);
  const openInvoice = (id: string) => { navigate('Invoices'); selectInvoice(id); };
  return <div className="project-page"><button className="text-link back-link" onClick={() => selectProject(null)}><ArrowLeft size={15}/>{' '}{t("All projects")}</button>
    <PageHeader eyebrow={clientName(state, project.clientId)} title={project.name} text={`${project.kind === 'fixed' ? t("Fixed price · {0} contract", money(project.fixedPriceMinor, currency)) : t("Hourly · {0}/h for new time", money(project.rateMinor, currency))} · ${statusLabels[project.status]}`}><Button variant="secondary" icon={Pencil} onClick={() => open('project', project.id)}>{t("Edit project")}</Button><Button variant="secondary" icon={Receipt} onClick={() => open('expense', undefined, project.id)}>{t("Add expense")}</Button><Button icon={Plus} onClick={() => open('time', undefined, project.id)}>{t("Log time")}</Button></PageHeader>
    <section className="metrics" aria-label={t("Project totals")}>
      <div className="metric"><span className="metric-label">{t("Contribution per actual hour")}</span><strong className={unknown ? 'unknown' : ''}><PerHour insight={insight} currency={currency}/></strong><small>{insight?.provisional ? t("Provisional · project in progress") : t("Lifetime · before overhead and taxes")}</small></div>
      <div className="metric"><span className="metric-label">{t("Direct contribution")}</span><strong className={insight?.contributionMinor == null ? 'unknown' : (insight.contributionMinor < 0 ? 'loss' : '')}>{insight?.contributionMinor == null ? <span className="unknown-value">{t("Unknown")}</span> : money(insight.contributionMinor, currency)}</strong><small>{money(insight?.revenueMinor ?? 0, currency)}{' '}{t("revenue −")}{' '}{money(insight?.directCostsMinor ?? 0, currency)}{' '}{t("costs")}{project.costsComplete ? '' : t(" so far")}</small></div>
      <div className="metric"><span className="metric-label">{t("Actual effort")}</span><strong>{hours(worked)}</strong><small>{hours(unpaid)}{' '}{t("non-billable included")}</small></div>
      <div className="metric"><span className="metric-label">{project.kind === 'fixed' ? t("Contract") : t("Ready to invoice")}</span><strong>{project.kind === 'fixed' ? money(insight?.contractedMinor ?? project.fixedPriceMinor, currency) : money(insight?.unbilledMinor ?? 0, currency)}</strong><small>{project.kind === 'fixed' ? (insight?.revenueMinor ? t("Agreed price; issued revenue shown left") : t("Agreed price · not revenue until issued")) : t("{0} approved, not yet on an invoice", hours(insight?.unbilledMinutes ?? 0))}</small></div>
    </section>
    {project.notes && <p className="project-notes preserve-lines">{project.notes}</p>}
    {!project.costsComplete && <div className="notice amber"><strong>{t("Contribution is unknown until direct costs are confirmed.")}</strong><p>{t("Record every direct cost for this project (or confirm there are none), then mark costs as complete in the project settings. Missing costs are never treated as zero.")}</p><Button variant="quiet" onClick={() => open('project', project.id)}>{t("Confirm direct costs")}</Button></div>}
    <div className="project-detail-grid"><section className="panel effort-panel"><PanelHeader title={t("Where the hours went")} text={t("Confirmed work by category, billable or not")}/>{worked ? <div className="effort-body"><div className="effort-split" aria-label={t("{0} billable and {1} non-billable", hours(billable), hours(unpaid))}><span className="billable" style={{ flexGrow: billable }}/><span className="unpaid" style={{ flexGrow: unpaid }}/></div><div className="effort-legend"><span><i className="billable"/>{t("Billable")}{' '}{hours(billable)}</span><span><i className="unpaid"/>{t("Non-billable")}{' '}{hours(unpaid)}</span></div>{billable > 0 && unpaid > 0 && <p className="effort-ratio">{t("For every billable hour,")}{' '}<strong>{Math.round(unpaid / billable * 60)}{' '}{t("min")}</strong>{' '}{t("of unbilled work came with it.")}</p>}<ul className="category-bars">{byCategory.map(item => <li key={item.category}><span>{item.category}</span><div className="bar-track"><div className="bar-fill" style={{ width: `${Math.max(2, item.minutes / worked * 100)}%` }}/></div><strong>{duration(item.minutes)}</strong></li>)}</ul>{pending.length > 0 && <p className="panel-note inline">{pending.length === 1 ? t('1 entry ({0}) awaiting review is not counted yet.', duration(sumMinutes(pending))) : t('{0} entries ({1}) awaiting review are not counted yet.', pending.length, duration(sumMinutes(pending)))}</p>}{project.kind === 'fixed' && project.status === 'active' && <p className="panel-note inline">{t("Estimated remaining work:")}{' '}{project.estimatedRemainingMinutes === null ? t("not set") : duration(project.estimatedRemainingMinutes)}{t(". Per-hour figures will change as work continues.")}</p>}</div> : <Empty title={t("No confirmed work yet.")} text={t("Log the delivery and the work around it: preparation, meetings and aftercare.")} action={t("Log time")} onAction={() => open('time', undefined, project.id)} icon={Clock3}/>}</section>
      <section className="panel"><PanelHeader title={t("Invoices")} text={t("Documents for this project")} action={t("Create invoice")} onAction={() => open('draft', undefined, project.id)}/>{invoices.length ? <ul className="mini-list">{invoices.map(invoice => <li key={invoice.id}><button onClick={() => openInvoice(invoice.id)}><span><strong>{invoice.number || t("Draft invoice")}</strong><small>{date(invoice.issueDate)}{' '}{t("· net")}{' '}{money(invoice.netMinor, invoice.currency)}</small></span><Status invoice={invoice}/><ArrowUpRight size={15}/></button></li>)}</ul> : <Empty title={t("Not invoiced yet.")} text={project.kind === 'fixed' ? t("The fixed contract is billed once. Its hours stay here to measure effort.") : t("Approved billable time can become a draft.")} icon={FileText}/>}</section></div>
    <section className="panel"><PanelHeader title={t("Time on this project")} text={t("{0} entries · all recorded work counts toward effort once confirmed", entries.length)}/>{entries.length ? <TimeTable state={state} open={open} run={run} busy={busy} entries={entries} onInvoice={openInvoice} showProject={false}/> : <Empty title={t("A fresh page.")} text={t("Time you log for this project appears here.")} icon={Clock3}/>}</section>
    <section className="panel"><PanelHeader title={t("Direct costs")} text={project.costsComplete ? t("Confirmed complete") : t("Not yet confirmed complete")} action={t("Add expense")} onAction={() => open('expense', undefined, project.id)}/>{expenses.length ? <ExpenseTable state={state} open={open} expenses={expenses} showProject={false}/> : <Empty title={project.costsComplete ? t("No direct costs — confirmed.") : t("No costs recorded yet.")} text={project.costsComplete ? t("You confirmed this project has no direct costs.") : t("Add materials, tools or subcontractors, or confirm there are none.")} icon={Receipt}/>}</section>
  </div>;
}

export function InvoicesPage(props: PageProps) {
  const { state, open, search, selectedInvoice } = props;
  const selected = state.invoices.find(invoice => invoice.id === selectedInvoice);
  if (selected) return <InvoiceDetail {...props} invoice={selected}/>;
  const invoices = [...state.invoices].reverse().filter(invoice => match(search, invoice.number || 'draft', invoice.client.name, projectName(state, invoice.projectId)));
  return <><PageHeader eyebrow={t("From work to payment")} title={t("Keep the money moving.")} text={t("Turn approved work into a clear invoice, then follow the receipts.")}><Button icon={Plus} disabled={!state.projects.length} onClick={() => open('draft')}>{t("Create invoice")}</Button></PageHeader><section className="panel"><PanelHeader title={t("Your invoices")} text={t("Drafts can be deleted and recreated. Issued documents are frozen.")}/>{invoices.length ? <InvoiceTable {...props} invoices={invoices} showDue/> : <Empty title={search ? t("No invoice matches this search.") : t("A clear invoice starts with clear work.")} text={search ? t("Try a number, client or project name.") : t("Create a draft from approved hours or your fixed-price contract. Review before issuing.")} action={state.projects.length && !search ? t("Create invoice") : undefined} onAction={() => open('draft')} icon={FileText}/>}</section><p className="footnote">{t("Downloading or printing a document does not send it or mark it paid. Payments change the outstanding balance; they do not count as revenue again.")}</p></>;
}

function Supplier({ invoice }: { invoice: Invoice }) {
  return <div>{invoice.business.logoId ? <img className="invoice-logo" src={`/api/attachments/${invoice.business.logoId}`} alt={t("{0} logo", invoice.business.name)}/> : <div className="invoice-wordmark">{invoice.business.name || t("Your business")}</div>}{invoice.business.logoId && <strong className="supplier-name">{invoice.business.name}</strong>}<p className="preserve-lines">{invoice.business.address}</p><p>{country(invoice.business.country)}</p>{invoice.business.taxId && <p>{t("VAT ID ·")}{' '}{invoice.business.taxId}</p>}{invoice.business.registrationId && <p>{t("Registration ·")}{' '}{invoice.business.registrationId}</p>}</div>;
}
export function InvoiceDocument({ invoice }: { invoice: Invoice }) {
  const draft = invoice.status === 'draft';
  const timed = invoice.lines.some(line => line.timeMinutes !== null);
  const base = invoice.business.currency, foreign = invoice.currency !== base;
  return <article className={`invoice-document ${draft ? 'is-draft' : ''}`} id="invoice-print"><div className="document-top"><Supplier invoice={invoice}/><div className="document-title"><span className="eyebrow">{draft ? t("For review") : t("Issued document")}</span><h2>{draft ? t("Draft invoice") : t("Invoice")}</h2>{draft && <span className="draft-stamp">{t("Draft · not issued")}</span>}<strong>{invoice.number || t("No number yet")}</strong></div></div>{draft && invoice.issueBlockers.length > 0 && <div className="document-blockers"><strong>{t("Not issuable as a final invoice in this release")}</strong><ul>{invoice.issueBlockers.map(blocker => <li key={blocker}>{t(blocker)}</li>)}</ul></div>}<div className="document-parties"><div><span className="document-label">{t("Bill to")}</span><strong>{invoice.client.name}</strong>{invoice.client.contactName && <p>{t("Attn.")}{' '}{invoice.client.contactName}</p>}<p className="preserve-lines">{invoice.client.address}</p><p>{country(invoice.client.country)}</p>{invoice.client.taxId && <p>{t("VAT ID ·")}{' '}{invoice.client.taxId}</p>}</div><dl><div><dt>{t("Invoice date")}</dt><dd>{date(invoice.issueDate)}</dd></div><div><dt>{t("Supply date")}</dt><dd>{date(invoice.supplyDate)}</dd></div><div><dt>{t("Payment due")}</dt><dd>{date(invoice.dueDate)}</dd></div></dl></div><table className="document-lines"><thead><tr><th>{t("Description")}</th><th className="numeric">{t("Qty / time")}</th><th className="numeric">{t("Rate")}</th><th className="numeric">{t("Tax")}</th><th className="numeric">{t("Net amount")}</th></tr></thead><tbody>{invoice.lines.map(line => <tr key={line.id}><td className="preserve-lines">{line.description}</td><td className="numeric">{line.timeMinutes === null ? line.quantity : <>{duration(line.timeMinutes)}<small className="cell-subtitle">{line.timeMinutes}{' '}{t("min")}</small></>}</td><td className="numeric">{money(line.unitPriceMinor, invoice.currency)}{line.timeMinutes !== null && <small className="cell-subtitle">{t("per hour")}</small>}</td><td className="numeric">{line.taxRate}%</td><td className="numeric">{money(line.netMinor, invoice.currency)}</td></tr>)}</tbody></table>{timed && <p className="document-time-note">{t("Time is charged by the exact minute at the hourly rate shown.")}</p>}<div className="document-totals"><div><span>{t("Subtotal")}</span><strong>{money(invoice.netMinor, invoice.currency)}</strong></div><div><span>{t("Tax")}</span><strong>{money(invoice.taxMinor, invoice.currency)}</strong></div><div className="document-total"><span>{t("Total")}{' '}{invoice.currency}</span><strong>{money(invoice.totalMinor, invoice.currency)}</strong></div>{foreign && invoice.taxMinor > 0 && <div><span>{t("VAT in")}{' '}{base}</span><strong>{money(invoice.baseTaxMinor, base)}</strong></div>}</div>{(invoice.taxTreatment === 'eu-reverse-charge' || invoice.taxTreatment === 'outside-eu' || foreign) && <div className="document-vat-note">{invoice.taxTreatment === 'eu-reverse-charge' && <p><strong>{t("VAT reverse-charged")}</strong>{' '}{t("(BTW verlegd) · Article 196 EU VAT Directive · Customer VAT ID")}{' '}{invoice.client.taxId || '—'}</p>}{invoice.taxTreatment === 'outside-eu' && <p><strong>{t("No Netherlands VAT")}</strong>{' '}{t("· service supplied to a customer outside the EU")}</p>}{foreign && <p>{t("Exchange rate · 1")}{' '}{base} = {invoice.exchangeRate} {invoice.currency}</p>}</div>}<div className="document-notes">{invoice.business.paymentInstructions && <div><span className="document-label">{t("Payment instructions")}</span><p className="preserve-lines">{invoice.business.paymentInstructions}</p></div>}{invoice.notes && <div><span className="document-label">{t("Notes")}</span><p className="preserve-lines">{invoice.notes}</p></div>}{draft && <p className="draft-notice">{t("DRAFT — For review only. This document has not been issued.")}</p>}</div>{draft && <div className="print-draft-mark" aria-hidden="true">{t("DRAFT · NOT ISSUED")}</div>}<footer className="document-footer">{invoice.business.name || t("Your business")} · {invoice.number || t("Draft document")}<span>{t("Thank you for your trust.")}</span></footer></article>;
}

function CreditDocument({ invoice, credit }: { invoice: Invoice; credit: CreditNote }) {
  return <article className="invoice-document" id="invoice-print">
    <div className="document-top"><Supplier invoice={invoice}/><div className="document-title"><span className="eyebrow">{t("Invoice correction")}</span><h2>{t("Credit note")}</h2><strong>{credit.number}</strong></div></div>
    <div className="document-parties"><div><span className="document-label">{t("Credit to")}</span><strong>{invoice.client.name}</strong><p className="preserve-lines">{invoice.client.address}</p><p>{country(invoice.client.country)}</p>{invoice.client.taxId && <p>{t("VAT ID ·")}{' '}{invoice.client.taxId}</p>}</div><dl><div><dt>{t("Credit date")}</dt><dd>{date(credit.date)}</dd></div><div><dt>{t("Original invoice")}</dt><dd>{invoice.number}</dd></div><div><dt>{t("Original date")}</dt><dd>{date(invoice.issueDate)}</dd></div></dl></div>
    <table className="document-lines"><thead><tr><th>{t("Description / reason")}</th><th className="numeric">{t("Qty")}</th><th className="numeric">{t("Rate")}</th><th className="numeric">{t("Tax")}</th><th className="numeric">{t("Net credit")}</th></tr></thead><tbody><tr><td className="preserve-lines">{credit.reason}</td><td className="numeric">1</td><td className="numeric">{money(credit.netMinor, invoice.currency)}</td><td className="numeric">{invoice.lines[0]?.taxRate}%</td><td className="numeric">{money(credit.netMinor, invoice.currency)}</td></tr></tbody></table>
    <div className="document-totals"><div><span>{t("Net credit")}</span><strong>{money(credit.netMinor, invoice.currency)}</strong></div><div><span>{t("Tax credit")}</span><strong>{money(credit.taxMinor, invoice.currency)}</strong></div><div className="document-total"><span>{t("Total credit")}{' '}{invoice.currency}</span><strong>{money(credit.totalMinor, invoice.currency)}</strong></div></div><div className="document-notes"><p>{t("This credit reduces the amount due on invoice")}{' '}{invoice.number}{t(". The original invoice remains unchanged. Payment receipts and any amount to refund are recorded separately.")}</p></div><footer className="document-footer">{invoice.business.name} · {credit.number}<span>{t("Correction to")}{' '}{invoice.number}</span></footer>
  </article>;
}

function InvoiceDetail(props: PageProps & { invoice: Invoice }) {
  const { invoice, state, open, selectInvoice, navigate, selectProject } = props;
  const payments = state.payments.filter(payment => payment.invoiceId === invoice.id);
  const credits = state.creditNotes.filter(credit => credit.invoiceId === invoice.id);
  const reserved = state.timeEntries.filter(entry => entry.invoiceId === invoice.id);
  const [selectedCreditId, setSelectedCreditId] = useState<string | null>(null);
  const selectedCredit = credits.find(credit => credit.id === selectedCreditId);
  return <div className="invoice-page"><button className="text-link back-link" onClick={() => selectInvoice(null)}><ArrowLeft size={15}/>{' '}{t("All invoices")}</button><PageHeader eyebrow={`${invoice.client.name} · ${projectName(state, invoice.projectId)}`} title={selectedCredit?.number || invoice.number || t("A draft, ready for review.")} text={invoice.status === 'issued' ? t("This document preserves the details and prices at the moment of issue.") : t("Check the client, dates, work and tax before issuing. To change lines or dates, delete the draft and create it again.")}><Button icon={Printer} variant="secondary" onClick={() => window.print()}>{t("Print / save PDF")}</Button>{invoice.status === 'draft' ? <><Button variant="quiet" icon={Trash2} onClick={() => open('deleteDraft', invoice.id)}>{t("Delete draft")}</Button>{invoice.issueBlockers.length === 0 && <Button onClick={() => open('issue', invoice.id)}>{t("Issue invoice")}</Button>}</> : <Button icon={Plus} onClick={() => open('payment', invoice.id)}>{t("Record payment")}</Button>}</PageHeader>
    {invoice.status === 'draft' && invoice.issueBlockers.length > 0 && <div className="notice amber"><strong>{t("This document stays a draft.")}</strong><p>{t("Final issuance is enabled for Netherlands suppliers: Dutch customers at 21% or 9%, EU business customers with reverse charge, and customers outside the EU. You can still review, print or save it as a draft.")}</p><ul>{invoice.issueBlockers.map(blocker => <li key={blocker}>{t(blocker)}</li>)}</ul><Button variant="quiet" onClick={() => open('settings')}>{t("Review business settings")}</Button></div>}
    <div className="invoice-layout">{selectedCredit ? <CreditDocument invoice={invoice} credit={selectedCredit}/> : <InvoiceDocument invoice={invoice}/>}<aside className="invoice-controls"><section className="panel invoice-summary">{selectedCredit && <><Badge tone="blue">{t("Credit note preview")}</Badge><p>{selectedCredit.number}{' '}{t("· Correction to")}{' '}{invoice.number}</p><Button variant="secondary" onClick={() => setSelectedCreditId(null)}>{t("Show original invoice")}</Button><div className="credit-preview-divider"/></>}<Status invoice={invoice}/><span className="summary-label">{invoice.outstandingMinor < 0 ? t("Amount to refund") : invoice.status === 'draft' ? t("Draft total") : t("Outstanding balance")}</span><strong>{money(invoice.status === 'draft' ? invoice.totalMinor : Math.abs(invoice.outstandingMinor), invoice.currency)}</strong><dl><div><dt>{t("Invoice total")}</dt><dd>{money(invoice.totalMinor, invoice.currency)}</dd></div><div><dt>{t("Receipts, net of reversals")}</dt><dd>{money(invoice.paidMinor, invoice.currency)}</dd></div><div><dt>{t("Credits")}</dt><dd>{money(invoice.creditedMinor, invoice.currency)}</dd></div>{invoice.currency !== state.workspace.currency && <div><dt>{t("In")}{' '}{state.workspace.currency}</dt><dd>{money(invoice.status === 'draft' ? invoice.baseTotalMinor : invoice.baseOutstandingMinor, state.workspace.currency)}{invoice.status === 'issued' && ' open'} · 1 {state.workspace.currency} = {invoice.exchangeRate} {invoice.currency}</dd></div>}{reserved.length > 0 && <div><dt>{invoice.status === 'draft' ? t("Time reserved") : t("Time invoiced")}</dt><dd>{duration(sumMinutes(reserved))} · {reserved.length === 1 ? t('1 entry') : t('{0} entries', reserved.length)}</dd></div>}</dl>{invoice.status === 'issued' && <Button variant="secondary" onClick={() => open('credit', invoice.id)}>{t("Add credit note")}</Button>}<button className="text-link summary-project-link" onClick={() => { navigate('Projects'); selectProject(invoice.projectId); }}>{t("Open project records")}{' '}<ArrowUpRight size={13}/></button><p>{invoice.status === 'draft' ? t("Reserved time is unavailable for other invoices and is released if you delete this draft.") : t("Receipts and credits are recorded separately. The original invoice stays intact.")}</p></section><div className="print-hint"><Printer size={19}/><p>{t("Choose “Save as PDF” in the print dialog. Disable browser headers and footers for a clean document. Printing does not mark the invoice as sent.")}</p></div></aside></div>
    {invoice.status === 'issued' && <section className="panel transactions"><PanelHeader title={t("Receipts & corrections")} text={t("An append-only trail for this invoice")}/>{!payments.length && !credits.length ? <Empty title={t("Waiting for the first receipt.")} text={t("Record partial or full payments here when the money actually arrives.")} action={t("Record payment")} onAction={() => open('payment', invoice.id)} icon={Wallet}/> : <div className="table-scroll"><table className="stack-table"><thead><tr><th>{t("Date")}</th><th>{t("Record")}</th><th>{t("Reference / reason")}</th><th className="numeric">{t("Amount")}</th><th aria-label={t("Actions")}/></tr></thead><tbody>{payments.map(payment => { const reversed = payments.some(other => other.reversalOf === payment.id); return <tr key={payment.id} className={reversed ? 'reversed-row' : ''}><td data-label={t("Date")}>{date(payment.date)}</td><td data-label={t("Record")}><Badge tone={payment.reversalOf ? 'amber' : 'green'}>{payment.reversalOf ? t("Payment reversal") : reversed ? t("Payment · reversed") : t("Payment")}</Badge></td><td className="primary-cell">{payment.reference || '—'}</td><td className="numeric" data-label={t("Amount")}>{money(payment.amountMinor, invoice.currency)}</td><td className="actions-cell">{!payment.reversalOf && !reversed && <Button variant="quiet" onClick={() => open('reversePayment', payment.id)}>{t("Reverse")}</Button>}</td></tr>; })}{credits.map(credit => <tr key={credit.id}><td data-label={t("Date")}>{date(credit.date)}</td><td data-label={t("Record")}><Badge tone="blue">{credit.number}</Badge></td><td className="primary-cell">{credit.reason}</td><td className="numeric" data-label={t("Amount")}>{money(-credit.totalMinor, invoice.currency)}</td><td className="actions-cell"><Button variant="quiet" icon={Printer} onClick={() => { setSelectedCreditId(credit.id); window.scrollTo({ top: 0 }); }}>{t("View / print")}</Button><small className="cell-subtitle">{t("Net")}{' '}{money(credit.netMinor, invoice.currency)}{' '}{t("· Tax")}{' '}{money(credit.taxMinor, invoice.currency)}</small></td></tr>)}</tbody></table></div>}</section>}
  </div>;
}

function ExpenseTable({ state, open, expenses, showProject = true }: { state: AppState; open: OpenModal; expenses: AppState['expenses']; showProject?: boolean }) {
  const currency = state.workspace.currency;
  return <div className="table-scroll"><table className="stack-table"><thead><tr><th>{t("Date")}</th><th>{t("Expense & supplier")}</th>{showProject && <th>{t("Belongs to")}</th>}<th className="numeric">{t("Net")}</th><th className="numeric">{t("VAT")}</th><th className="numeric">{t("Cost")}</th><th>{t("Attachment")}</th><th aria-label={t("Actions")}/></tr></thead><tbody>{expenses.map(expense => { const file = state.attachments.find(item => item.id === expense.attachmentId); const reverse = !['standard', 'none'].includes(expense.vatTreatment); return <tr key={expense.id}><td className="nowrap" data-label={t("Date")}>{date(expense.date)}</td><td className="primary-cell"><strong>{expense.description}</strong><small className="cell-subtitle">{[expense.supplier, expense.category, country(expense.country), expense.paymentMethod].filter(Boolean).join(' · ') || t("No supplier details")}</small></td>{showProject && <td data-label={t("Belongs to")}>{expense.projectId ? <>{projectName(state, expense.projectId)}<small className="cell-subtitle">{projectClient(state, expense.projectId)}</small></> : <Badge>{t("General cost")}</Badge>}</td>}<td className="numeric" data-label={t("Net")}>{money(expense.netMinor, currency)}{expense.originalAmountMinor !== null && expense.originalCurrency && expense.originalCurrency !== currency && <small className="cell-subtitle">{money(expense.originalAmountMinor, expense.originalCurrency)}{' '}{t("charged")}</small>}</td><td className="numeric" data-label={t("VAT")}>{expense.vatTreatment === 'none' ? '—' : money(reverse ? expense.reverseChargeTaxMinor : expense.taxMinor, currency)}<small className="cell-subtitle">{reverse ? t("Reverse charge · self-assessed") : expense.vatTreatment === 'none' ? t("No VAT") : expense.deductibleTax ? t("Deductible") : t("Not deductible · in cost")}</small></td><td className="numeric" data-label={t("Cost")}><strong>{money(expense.costMinor, currency)}</strong></td><td data-label={t("Attachment")}>{expense.attachmentId ? <a className="text-link attachment-link" href={`/api/attachments/${expense.attachmentId}`} target="_blank" rel="noreferrer" title={file?.name}><Paperclip size={15}/><span>{file?.name || t("Original attachment")}</span></a> : <span className="muted">{t("No attachment")}</span>}</td><td className="actions-cell"><div className="row-actions"><button className="icon-button" onClick={() => open('expense', expense.id)} aria-label={t("Edit {0}", expense.description)}><Pencil size={16}/></button><button className="icon-button" onClick={() => open('deleteExpense', expense.id)} aria-label={t("Delete {0}", expense.description)}><Trash2 size={16}/></button></div></td></tr>; })}</tbody></table></div>;
}

export function ExpensesPage({ state, open, search }: PageProps) {
  const [filter, setFilter] = useState('all');
  const currency = state.workspace.currency;
  const expenses = [...state.expenses].sort(newestFirst).filter(expense => match(search, expense.description, expense.supplier, expense.category, expense.supplierInvoiceNumber, expense.projectId ? `${projectName(state, expense.projectId)} ${projectClient(state, expense.projectId)}` : 'general cost')).filter(expense => filter === 'all' || (filter === 'project') === (expense.projectId !== null));
  const general = state.expenses.filter(expense => expense.projectId === null).length;
  return <><PageHeader eyebrow={t("The cost of doing business")} title={t("Keep the full picture.")} text={t("Project costs and general business costs, with VAT and the original attachments close at hand.")}><Button icon={Plus} onClick={() => open('expense')}>{t("Add expense")}</Button></PageHeader><div className="expense-note"><Receipt size={21}/><p>{t("Project costs reduce a project's direct contribution. General costs, such as software or your phone, count toward your yearly result and VAT return.")}</p><span className="expense-note-total">{money(state.totals.directCostsMinor, currency)}<small>{t("project costs")}</small></span><span className="expense-note-total">{money(state.totals.generalCostsMinor, currency)}<small>{t("general costs")}</small></span></div><section className="panel"><div className="table-toolbar"><div className="tabs" role="tablist" aria-label={t("Filter expenses")}>{[['all', t("All costs")], ['project', t("Project costs")], ['general', t("General costs{0}", general ? ` · ${general}` : '')]].map(([value, label]) => <button key={value} role="tab" aria-selected={filter === value} className={filter === value ? 'active' : ''} onClick={() => setFilter(value)}>{label}</button>)}</div><span className="muted count">{expenses.length}{' '}{t("expenses")}</span></div>{expenses.length ? <ExpenseTable state={state} open={open} expenses={expenses}/> : <Empty title={search || filter !== 'all' ? t("Nothing matches this view.") : t("Even small costs deserve a place.")} text={search || filter !== 'all' ? t("Try another filter or search term.") : t("Add subscriptions, tools, travel or subcontractors, with or without a project.")} action={!search && filter === 'all' ? t("Add expense") : undefined} onAction={() => open('expense')} icon={Receipt}/>}</section><p className="footnote">{t("Book amounts in")}{' '}{currency}{t("; for foreign purchases keep the original amount for reference. When you have recorded all direct costs of a project, mark them as confirmed to see its contribution.")}</p></>;
}

export function ReportsPage({ state, open }: PageProps) {
  const currency = state.workspace.currency;
  const [periodKey, setPeriodKey] = useState(() => (openVatPeriod(state) ?? state.vatPeriods[0])?.period ?? '');
  const period = state.vatPeriods.find(item => item.period === periodKey) ?? state.vatPeriods[0];
  const years = state.years.map(item => item.year);
  const [year, setYear] = useState(years[0] ?? today().slice(0, 4));
  const summary = state.years.find(item => item.year === year);
  const months = state.months.filter(month => month.month.startsWith(year));
  const peak = Math.max(1, ...months.map(month => Math.max(Math.abs(month.revenueMinor), month.costsMinor)));
  const monthKeys = Array.from({ length: 12 }, (_, index) => `${year}-${String(index + 1).padStart(2, '0')}`);
  const confirmed = state.timeEntries.filter(entry => entry.approved && entry.date.startsWith(year));
  const projectRows = state.projects.filter(project => confirmed.some(entry => entry.projectId === project.id));
  const filing = (item: VatPeriod) => item.filing?.status === 'filed' ? <Badge tone="green">{t("Filed")}{item.filing.filedOn ? ` · ${date(item.filing.filedOn)}` : ''}</Badge> : item.filing?.status === 'not-applicable' ? <Badge>{t("Not applicable")}</Badge> : item.end < today() ? <Badge tone="amber">{t("To do")}</Badge> : <Badge tone="blue">{t("Current period")}</Badge>;
  return <><PageHeader eyebrow={t("Bookkeeping, without the spreadsheet")} title={t("Your numbers, period by period.")} text={t("VAT return figures, monthly results and where your hours went.")}/>
    {period ? <section className="panel vat-panel"><PanelHeader title={t("VAT return")} text={t("Box-by-box figures in the Netherlands return layout. Copy the boxes marked “Fill in” into your tax portal.")}/><div className="table-toolbar vat-toolbar"><label className="period-select"><span>{t("Period")}</span><select value={period.period} onChange={event => setPeriodKey(event.target.value)}>{state.vatPeriods.map(item => <option key={item.period} value={item.period}>{item.period}{item.filing?.status === 'filed' ? t(" · filed") : ''}</option>)}</select></label><span className="muted">{date(period.start)} – {date(period.end)}</span>{filing(period)}<Button variant="secondary" onClick={() => open('vatFiling', period.period)}>{t("Update status")}</Button></div>
      {state.business.smallBusinessScheme && <div className="notice amber"><strong>{t("Small business scheme is on.")}</strong><p>{t("You charge and reclaim no VAT. Reverse-charged purchases may still need a return; check your situation.")}</p></div>}
      <div className="table-scroll"><table className="stack-table vat-table"><thead><tr><th>{t("Box")}</th><th>{t("Description")}</th><th className="numeric">{t("Amount")}</th><th className="numeric">{t("VAT")}</th><th>{t("Action")}</th></tr></thead><tbody>{period.rows.map(row => { const filled = row.netMinor !== 0 || row.taxMinor !== 0; return <tr key={row.code} className={filled ? 'vat-filled' : 'vat-empty'}><td data-label={t("Box")}><strong>{row.code === 'outside' ? '—' : row.code}</strong></td><td className="primary-cell">{t(row.label)}</td><td className="numeric" data-label={t("Amount")}>{money(row.netMinor, currency)}</td><td className="numeric" data-label={t("VAT")}>{['1e', '3b', 'outside'].includes(row.code) ? '—' : money(row.taxMinor, currency)}</td><td data-label={t("Action")}>{filled && row.code !== 'outside' ? <Badge tone="blue">{t("Fill in")}</Badge> : <span className="muted">{filled ? t("Check") : t("Not needed")}</span>}</td></tr>; })}
        <tr className="vat-sum"><td><strong>5a</strong></td><td className="primary-cell">{t("VAT due")}</td><td/><td className="numeric" data-label={t("VAT")}>{money(period.dueMinor, currency)}</td><td/></tr>
        <tr className="vat-sum"><td><strong>5b</strong></td><td className="primary-cell">{t("Input VAT you may deduct")}</td><td/><td className="numeric" data-label={t("VAT")}>{money(period.inputMinor, currency)}</td><td/></tr>
        <tr className="vat-total"><td/><td className="primary-cell"><strong>{period.balanceMinor < 0 ? t("To reclaim") : t("To pay")}</strong></td><td/><td className="numeric" data-label={t("Balance")}><strong>{money(Math.abs(period.balanceMinor), currency)}</strong></td><td/></tr></tbody></table></div>
      <p className="panel-note">{t("Sales count on the invoice date, credit notes on their own date and costs on the expense date. Foreign-currency invoices use their own exchange rate. Billable does not file returns; check the figures before you submit.")}</p>
      <div className="form-section-heading"><h3>{t("Filing status per period")}</h3></div><div className="table-scroll"><table className="stack-table"><thead><tr><th>{t("Period")}</th><th className="numeric">{t("Balance")}</th><th>{t("Status")}</th><th>{t("Note")}</th><th aria-label={t("Actions")}/></tr></thead><tbody>{state.vatPeriods.map(item => <tr key={item.period}><td className="primary-cell"><strong>{item.period}</strong></td><td className="numeric" data-label={t("Balance")}>{money(Math.abs(item.balanceMinor), currency)} <small className="muted">{item.balanceMinor < 0 ? 'reclaim' : 'pay'}</small></td><td data-label={t("Status")}>{filing(item)}</td><td data-label={t("Note")}>{item.filing?.note || <span className="muted">—</span>}</td><td className="actions-cell"><Button variant="quiet" onClick={() => open('vatFiling', item.period)}>{t("Update")}</Button></td></tr>)}</tbody></table></div>
    </section> : null}
    <section className="panel"><PanelHeader title={t("Year overview")} text={t("Net revenue from issued invoices less credits, all costs and the result, month by month")}/>{state.months.length ? <><div className="table-toolbar"><div className="tabs" role="tablist" aria-label={t("Choose year")}>{years.map(item => <button key={item} role="tab" aria-selected={year === item} className={year === item ? 'active' : ''} onClick={() => setYear(item)}>{item}</button>)}</div><span className="chart-legend"><i className="revenue"/>{t("Revenue")}{' '}<i className="costs"/>{t("Costs")}</span></div>
      {summary && <section className="metrics compact" aria-label={t("Totals {0}", year)}><div className="metric"><span className="metric-label">{t("Revenue")}{' '}{year}</span><strong>{money(summary.revenueMinor, currency)}</strong><small>{t("Net, excluding VAT")}</small></div><div className="metric"><span className="metric-label">{t("Costs")}{' '}{year}</span><strong>{money(summary.costsMinor, currency)}</strong><small>{t("Project and general costs")}</small></div><div className="metric"><span className="metric-label">{t("Result")}{' '}{year}</span><strong className={summary.resultMinor < 0 ? 'loss' : ''}>{money(summary.resultMinor, currency)}</strong><small>{t("Before income tax")}</small></div><div className="metric"><span className="metric-label">{t("Hours")}{' '}{year}</span><strong>{hours(summary.workedMinutes)}</strong><small>{hours(summary.billableMinutes)}{' '}{t("billable")}</small></div></section>}
      <div className="month-chart" aria-hidden="true">{monthKeys.map(key => { const month = months.find(item => item.month === key); return <div className="month-col" key={key} title={month ? t("{0}: {1} revenue, {2} costs", key, money(month.revenueMinor, currency), money(month.costsMinor, currency)) : key}><div className="month-bars">{month && <><span className="revenue" style={{ height: `${Math.max(0, month.revenueMinor) / peak * 100}%` }}/><span className="costs" style={{ height: `${month.costsMinor / peak * 100}%` }}/></>}</div><small>{monthLabel(key)}</small></div>; })}</div>
      <div className="table-scroll"><table className="stack-table"><thead><tr><th>{t("Month")}</th><th className="numeric">{t("Revenue")}</th><th className="numeric">{t("Costs")}</th><th className="numeric">{t("Result")}</th><th className="numeric">{t("Cumulative")}</th><th className="numeric">{t("Hours")}</th></tr></thead><tbody>{months.map(month => <tr key={month.month}><td className="primary-cell"><strong>{new Date(`${month.month}-01T12:00:00`).toLocaleDateString(locale(), { month: 'long', year: 'numeric' })}</strong></td><td className="numeric" data-label={t("Revenue")}>{money(month.revenueMinor, currency)}</td><td className="numeric" data-label={t("Costs")}>{money(month.costsMinor, currency)}</td><td className={`numeric ${month.resultMinor < 0 ? 'loss' : ''}`} data-label={t("Result")}>{money(month.resultMinor, currency)}</td><td className="numeric" data-label={t("Cumulative")}>{money(month.cumulativeMinor, currency)}</td><td className="numeric" data-label={t("Hours")}>{hours(month.workedMinutes)}<small className="cell-subtitle">{hours(month.billableMinutes)}{' '}{t("billable")}</small></td></tr>)}</tbody></table></div>
      <p className="panel-note">{t("Cumulative runs from your first recorded month. Revenue is what you invoiced, not what was paid; see Invoices for receipts.")}</p></> : <Empty title={t("Your first month will show up here.")} text={t("Issue an invoice, record a cost or confirm some time to start the overview.")} icon={ChartColumn}/>}</section>
    {projectRows.length > 0 && <section className="panel"><PanelHeader title={t("Hours per project")} text={t("Confirmed work in {0}, billable and non-billable", year)}/><div className="table-scroll"><table className="hours-grid"><thead><tr><th>{t("Project")}</th>{monthKeys.map(month => <th key={month} className="numeric">{monthLabel(month)}</th>)}<th className="numeric">{t("Total")}</th></tr></thead><tbody>{projectRows.map(project => { const entries = confirmed.filter(entry => entry.projectId === project.id); return <tr key={project.id}><td><strong>{project.name}</strong><small className="cell-subtitle">{clientName(state, project.clientId)}</small></td>{monthKeys.map(month => { const minutes = sumMinutes(entries.filter(entry => entry.date.startsWith(month))); return <td key={month} className={`numeric ${minutes ? '' : 'muted'}`}>{minutes ? hours(minutes) : '·'}</td>; })}<td className="numeric"><strong>{hours(sumMinutes(entries))}</strong></td></tr>; })}</tbody></table></div></section>}
  </>;
}
